import fs from 'fs/promises';
import path from 'path';
import { unstable_cache } from 'next/cache';

const DB_PATH = path.join(process.cwd(), 'posts.json');

export interface Post {
  id: string;
  title: string;
  content: string;
  createdAt: string;
}

async function readDb(): Promise<Post[]> {
  try {
    const data = await fs.readFile(DB_PATH, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    return [];
  }
}

async function writeDb(posts: Post[]) {
  await fs.writeFile(DB_PATH, JSON.stringify(posts, null, 2));
}

export const getPosts = unstable_cache(
  async () => {
    return readDb();
  },
  ['posts-list'],
  { tags: ['posts'] }
);

export async function addPost(title: string, content: string): Promise<Post> {
  const posts = await readDb();
  const newPost: Post = {
    id: Date.now().toString(),
    title,
    content,
    createdAt: new Date().toISOString(),
  };
  posts.push(newPost);
  await writeDb(posts);
  return newPost;
}

