'use server';

import { addPost } from '@/lib/data';
import { updateTag } from 'next/cache';
import { redirect } from 'next/navigation';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title || !content) {
    throw new Error('Title and content are required');
  }

  await addPost(title, content);

  // Invalidate cache tags so the new post is immediately visible
  // 'posts' tag: affects any page that displays a list of posts
  // This guarantees fresh data on the next fetch
  updateTag('posts');

  // Redirect or revalidate path is often used too, but updateTag handles the data freshness.
  // We'll redirect to home to refresh the view.
  redirect('/');
}

