import { getPosts } from '@/lib/data';
import { createPost } from './actions';

export default async function Home() {
  const posts = await getPosts();

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Posts</h1>
      <p>Current Posts: {posts.length}</p>

      <ul style={{ marginBottom: '2rem' }}>
        {posts.map((post) => (
          <li key={post.id} style={{ border: '1px solid #ccc', padding: '1rem', marginBottom: '1rem' }}>
            <h3>{post.title}</h3>
            <p>{post.content}</p>
            <small>{new Date(post.createdAt).toLocaleString()}</small>
          </li>
        ))}
      </ul>

      <hr />

      <h2>Create New Post</h2>
      <form action={createPost} style={{ display: 'flex', flexDirection: 'column', gap: '1rem', maxWidth: '400px' }}>
        <input name="title" placeholder="Title" required style={{ padding: '0.5rem' }} />
        <textarea name="content" placeholder="Content" required style={{ padding: '0.5rem', minHeight: '100px' }} />
        <button type="submit" style={{ padding: '0.5rem', background: 'blue', color: 'white', border: 'none' }}>
          Create Post
        </button>
      </form>
    </main>
  );
}

